// Package gen renders templates into a project directory.
package gen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"go/format"
	"io"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"github.com/Imanuelkarl/forge/internal/assets"
)

// Kind decides what happens when a target file already exists.
type Kind int

const (
	// Scaffold files are written once and then belong to the developer: they are
	// only overwritten while they still match what goforge last wrote (or with --force).
	Scaffold Kind = iota
	// Generated files ("Code generated ... DO NOT EDIT.") are always overwritten.
	Generated
)

const manifestPath = ".forge/manifest.json"

// ModuleState remembers what goforge generated for a module.
type ModuleState struct {
	Generated bool   `json:"generated"`
	Migration string `json:"migration,omitempty"`
	UpHash    string `json:"up_hash,omitempty"`
}

// Manifest records a hash of every file goforge wrote, so it can tell later whether a
// developer edited it.
type Manifest struct {
	Files   map[string]string      `json:"files"`
	Modules map[string]ModuleState `json:"modules"`
}

// LoadManifest reads .forge/manifest.json (an absent file yields an empty manifest).
func LoadManifest(root string) (*Manifest, error) {
	m := &Manifest{Files: map[string]string{}, Modules: map[string]ModuleState{}}
	b, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(manifestPath)))
	if errors.Is(err, os.ErrNotExist) {
		return m, nil
	}
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(b, m); err != nil {
		return nil, fmt.Errorf("read %s: %w", manifestPath, err)
	}
	if m.Files == nil {
		m.Files = map[string]string{}
	}
	if m.Modules == nil {
		m.Modules = map[string]ModuleState{}
	}
	return m, nil
}

// Save writes the manifest to disk.
func (m *Manifest) Save(root string) error {
	b, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	path := filepath.Join(root, filepath.FromSlash(manifestPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, append(b, '\n'), 0o644)
}

// Writer writes files, formats Go code and keeps the manifest up to date.
type Writer struct {
	Root     string
	DryRun   bool
	Force    bool
	Manifest *Manifest
	Out      io.Writer

	Written int
	// Skipped are scaffold files goforge wrote earlier and you edited since.
	Skipped []string
	// Kept are files that existed before goforge and are left as they are.
	Kept []string
	// Conflicts are new Go files that were not written because they would clash with
	// code already in their package.
	Conflicts    []string
	FormatErrors []string
}

// generatedHeader starts every Generated file; an untracked file that carries it was
// written by goforge (e.g. before the manifest was lost) and may be regenerated.
const generatedHeader = "// Code generated by goforge. DO NOT EDIT."

// NewWriter creates a Writer for the project at root.
func NewWriter(root string, dryRun, force bool, out io.Writer) (*Writer, error) {
	mf, err := LoadManifest(root)
	if err != nil {
		return nil, err
	}
	return &Writer{Root: root, DryRun: dryRun, Force: force, Manifest: mf, Out: out}, nil
}

func (w *Writer) logf(format string, args ...any) {
	fmt.Fprintf(w.Out, format+"\n", args...)
}

func hashBytes(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// action is what Write will do with a file.
type action int

const (
	actCreate    action = iota
	actUpdate           // overwrite a file goforge owns
	actUnchanged        // already has exactly this content
	actKeep             // exists, but goforge did not write it: it is yours
	actEdited           // goforge wrote it, you edited it since
	actConflict         // new Go file that would break the package it lands in
)

// normalize gofmts Go code and ensures a trailing newline. formatErr is set when Go code
// does not parse.
func normalize(rel string, content []byte) (out []byte, formatErr error) {
	if strings.HasSuffix(rel, ".go") {
		if formatted, err := format.Source(content); err != nil {
			formatErr = err
		} else {
			content = formatted
		}
	}
	if len(content) == 0 || content[len(content)-1] != '\n' {
		content = append(content, '\n')
	}
	return content, formatErr
}

// plan decides what writing (normalized) content to rel would do, without writing.
func (w *Writer) plan(rel string, content []byte, kind Kind) (act action, reason string, err error) {
	abs := filepath.Join(w.Root, filepath.FromSlash(rel))
	existing, err := os.ReadFile(abs)
	if errors.Is(err, os.ErrNotExist) {
		if strings.HasSuffix(rel, ".go") {
			if reason := goConflict(abs, content); reason != "" {
				return actConflict, reason, nil
			}
		}
		return actCreate, "", nil
	}
	if err != nil {
		return 0, "", err
	}

	cur := hashBytes(existing)
	if cur == hashBytes(content) {
		return actUnchanged, "", nil
	}
	if w.Force {
		return actUpdate, "", nil
	}
	prev, tracked := w.Manifest.Files[rel]
	switch {
	case !tracked && (kind == Scaffold || !bytes.HasPrefix(existing, []byte(generatedHeader))):
		// A file goforge never wrote (e.g. from a project adopted with `goforge init`):
		// it is yours, whatever its name.
		return actKeep, "", nil
	case tracked && kind == Scaffold && prev != cur:
		return actEdited, "", nil
	}
	return actUpdate, "", nil
}

// Blocked reports whether Write would leave rel alone because it is your file or
// because it would clash with your code.
func (w *Writer) Blocked(rel string, content []byte, kind Kind) (bool, error) {
	rel = filepath.ToSlash(rel)
	content, _ = normalize(rel, content)
	act, _, err := w.plan(rel, content, kind)
	return act == actKeep || act == actConflict, err
}

// Hold records that rel was not written because it depends on code goforge could not add.
func (w *Writer) Hold(rel, reason string) {
	rel = filepath.ToSlash(rel)
	w.Conflicts = append(w.Conflicts, rel+": "+reason)
	w.logf("  hold     %s (%s)", rel, reason)
}

// Write stores content at rel (slash-separated, relative to the project root).
func (w *Writer) Write(rel string, content []byte, kind Kind) error {
	rel = filepath.ToSlash(rel)

	content, formatErr := normalize(rel, content)
	if formatErr != nil {
		w.FormatErrors = append(w.FormatErrors, fmt.Sprintf("%s: %v", rel, formatErr))
	}

	act, reason, err := w.plan(rel, content, kind)
	if err != nil {
		return err
	}
	abs := filepath.Join(w.Root, filepath.FromSlash(rel))
	sum := hashBytes(content)

	switch act {
	case actUnchanged:
		w.Manifest.Files[rel] = sum
		return nil
	case actKeep:
		w.Kept = append(w.Kept, rel)
		w.logf("  keep     %s (your file; goforge does not manage it)", rel)
		return nil
	case actEdited:
		w.Skipped = append(w.Skipped, rel)
		w.logf("  skip     %s (edited by you)", rel)
		return nil
	case actConflict:
		w.Conflicts = append(w.Conflicts, rel+": "+reason)
		w.logf("  conflict %s (%s)", rel, reason)
		return nil
	}

	verb := "create"
	if act == actUpdate {
		verb = "update"
	}
	if w.DryRun {
		w.logf("  would %s %s", verb, rel)
		return nil
	}

	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(abs, content, 0o644); err != nil {
		return err
	}
	w.Manifest.Files[rel] = sum
	w.Written++
	w.logf("  %s   %s", verb, rel)
	return nil
}

// Finish saves the manifest and prints a summary. It returns an error if any Go file failed to format.
func (w *Writer) Finish() error {
	if !w.DryRun {
		if err := w.Manifest.Save(w.Root); err != nil {
			return err
		}
	}

	if len(w.Skipped) > 0 {
		w.logf("\n%d file(s) were edited by you and left untouched (use --force to overwrite):", len(w.Skipped))
		for _, s := range w.Skipped {
			w.logf("  - %s", s)
		}
		w.logf("If the schema changed, review them by hand so they match the regenerated code.")
	}
	if len(w.Kept) > 0 {
		w.logf("\n%d existing file(s) were not created by goforge and were left untouched.", len(w.Kept))
	}
	if len(w.Conflicts) > 0 {
		w.logf("\n%d file(s) were not written so they would not clash with your code:", len(w.Conflicts))
		for _, c := range w.Conflicts {
			w.logf("  - %s", c)
		}
		w.logf("Your code is unchanged. To get these files later, rename or move the clashing code and re-run the command.")
	}
	if len(w.FormatErrors) > 0 {
		w.logf("\ngenerated code that does not parse (this is a goforge bug, please report it):")
		for _, e := range w.FormatErrors {
			w.logf("  - %s", e)
		}
		return fmt.Errorf("%d generated file(s) failed gofmt", len(w.FormatErrors))
	}
	return nil
}

// render executes the embedded template at path with data.
func render(path string, data any) ([]byte, error) {
	b, err := assets.FS.ReadFile("templates/" + path)
	if err != nil {
		return nil, err
	}
	t, err := template.New(path).Parse(string(b))
	if err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return nil, fmt.Errorf("render %s: %w", path, err)
	}
	return buf.Bytes(), nil
}
